/* Atelier — the techniques library, part 2: colour, materials and media, subjects, teaching methods */
'use strict';

TECH.push(
  /* ---------- colour ---------- */
  { id: 'colour-wheel', s: 'colour', n: 'The colour wheel and mixing', sum: 'Primaries, secondaries, tertiaries and how they mix.', lvl: 1, mins: 40, ill: 'wheel',
    what: 'The colour wheel arranges hues in a circle. Red, yellow and blue are the traditional primaries. Mixing pairs of them makes the secondaries (orange, green and violet), and mixing a primary with a neighbouring secondary makes the tertiaries, such as blue-green. Colours opposite each other are complements.',
    why: 'It’s the foundation for mixing paint, choosing colour schemes and understanding why some mixes turn muddy.',
    steps: ['Draw a circle divided into 12 segments.', 'Paint the primaries in every fourth segment.', 'Mix the secondaries between them, adding the darker colour to the lighter one a little at a time.', 'Mix the tertiaries in the remaining spaces.', 'Label each segment.', 'Find and mark the complementary pairs.'],
    tips: ['Add dark to light gradually: blue into yellow, not yellow into blue.', 'A warm and a cool version of each primary (such as lemon yellow and a warm yellow) gives cleaner mixes.', 'Keep water and brushes clean between mixes.'],
    mistakes: ['Muddy mixes from dirty water or too many colours.', 'Mixing equal amounts, so the darker colour takes over.', 'Forgetting to label.'],
    ex: 'Paint a 12-part colour wheel from red, yellow and blue.',
    kids: 'Mix secondaries by squishing paint in zip-lock bags, or paint a colour wheel pizza.',
    adults: 'Make a mixing chart of every pair of colours in your palette.',
    mat: ['Red, yellow and blue paint (acrylic, gouache or watercolour)', 'White', 'Palette', 'Brushes', 'Paper'], rel: ['schemes', 'tints-shades', 'neutrals'] },
  { id: 'hue-value-sat', s: 'colour', n: 'Hue, value and saturation', sum: 'The three properties of every colour.', lvl: 2, mins: 30, ill: 'hsv',
    what: 'Every colour has three properties: hue (where it sits on the wheel, such as red or green), value (how light or dark it is) and saturation, also called chroma (how vivid or greyed it is).',
    why: 'Getting the value right matters more than getting the hue right. Understanding saturation helps students mix natural-looking colour, because most colours in nature are far less vivid than paint straight from the tube.',
    steps: ['Choose one hue.', 'Make a value strip: lighten it with white and darken it with its complement or black.', 'Make a saturation strip: mix it step by step towards a grey of the same value.', 'Photograph the strips in black and white to check their values.', 'Pick colours in a photo and name each one’s hue, value and saturation.'],
    tips: ['Yellow is naturally light and violet naturally dark.', 'Greying backgrounds pushes them back.', 'A phone’s black-and-white filter makes a great value checker.'],
    mistakes: ['Blaming the colour when the value is the real problem.', 'Using every colour at full strength.', 'Confusing dark with vivid.'],
    ex: 'Paint a value strip and a saturation strip for one hue.',
    kids: 'Sort paint chips by hue, then by light and dark.',
    adults: 'Paint a still life in a limited palette, focusing on value first.',
    mat: ['Paint: one colour, white and its complement', 'Palette', 'Paper'], rel: ['colour-wheel', 'tints-shades', 'value-scale'] },
  { id: 'schemes', s: 'colour', n: 'Colour schemes', sum: 'Complementary, analogous and triadic harmonies.', lvl: 2, mins: 30, ill: 'schemes',
    what: 'A colour scheme is a planned set of colours. Complementary schemes use opposites (blue and orange) for contrast, analogous schemes use neighbours (blue, blue-green and green) for harmony, and triadic schemes use three evenly spaced hues (red, yellow and blue) for balanced variety.',
    why: 'Choosing a scheme before starting gives a painting unity and mood, and avoids rainbow overload.',
    steps: ['Decide on the mood: calm, energetic, warm or cool.', 'Choose a scheme from the wheel.', 'Pick one colour to dominate, another to support it and a small accent.', 'Mix every colour from the scheme, including greys made from the complements.', 'Use the accent at the focal point.'],
    tips: ['A 60-30-10 split (dominant, supporting, accent) is a handy guide.', 'Complements side by side vibrate; mixed together they make neutrals.', 'Analogous schemes are forgiving for beginners.'],
    mistakes: ['Using every colour in equal amounts.', 'Forgetting neutrals, which rest the eye.', 'Choosing a scheme, then adding extra colours anyway.'],
    ex: 'Paint a complementary picture, such as an orange fish in blue water, then an analogous one.',
    kids: 'Make a collage from magazine scraps in neighbouring colours only.',
    adults: 'Repaint a photo in three different schemes and compare the moods.',
    mat: ['Paints or coloured pencils', 'Colour wheel', 'Paper'], rel: ['colour-wheel', 'temperature', 'neutrals'] },
  { id: 'temperature', s: 'colour', n: 'Warm and cool colour', sum: 'Using colour temperature for depth, light and mood.', lvl: 2, mins: 30, ill: 'temp',
    what: 'Colours feel warm (reds, oranges, yellows) or cool (blues, greens, violets), and each colour also comes in warmer and cooler versions, such as an orangey red and a pinkish red. Warm colours seem to come forward and cool colours seem to sit back.',
    why: 'Temperature creates depth, makes light convincing (warm light usually means cool shadows) and sets the mood.',
    steps: ['Sort your paints into warm and cool.', 'Decide the temperature of the light. Warm sunlight usually means cooler shadows.', 'Paint lit areas with warmer mixes and shadows with cooler ones.', 'Use cooler, paler colour in the distance and warmer, stronger colour up close.', 'Compare a warm and a cool version of the same scene.'],
    tips: ['Shadows rarely just get darker. They usually shift in temperature too.', 'Even greys can be warm or cool.', 'Sunset and overcast photos show temperature shifts clearly.'],
    mistakes: ['Shading only with black.', 'Warm colours in the far distance.', 'No temperature difference between light and shadow.'],
    ex: 'Paint the same small scene twice, once warm and once cool, and discuss the mood.',
    kids: 'Sort crayons into warm and cool, then make a warm sun and cool sea picture.',
    adults: 'Paint a still life with warm light and cool shadows.',
    mat: ['Paints or coloured pencils', 'Paper'], rel: ['atmospheric', 'schemes', 'neutrals'] },
  { id: 'tints-shades', s: 'colour', n: 'Tints, tones and shades', sum: 'A colour mixed with white, grey or black.', lvl: 1, mins: 25, ill: 'tints',
    what: 'A tint is a colour mixed with white (lighter), a shade is a colour mixed with black or a dark complement (darker), and a tone is a colour mixed with grey (less vivid). Together they make a full range from a single colour.',
    why: 'It teaches value control in colour and is the basis of one-colour paintings.',
    steps: ['Put the pure colour in the middle of a strip.', 'To the left, add white bit by bit to make tints.', 'To the right, add a dark (black or a dark complement) bit by bit to make shades.', 'Underneath, mix the colour with grey to make tones.', 'Paint a small object using only these mixes.'],
    tips: ['Add colour to white rather than white to colour; it saves paint.', 'Black makes some colours dull or greenish (yellow especially), so try a dark complement instead.', 'Keep the steps even.'],
    mistakes: ['Big jumps between steps.', 'Muddy shades from too much black.', 'Not cleaning the brush between mixes.'],
    ex: 'Paint a one-colour picture of a simple object using tints and shades.',
    kids: 'Paint a one-colour monster in light and dark versions of a favourite colour.',
    adults: 'Paint a one-colour landscape study in tints and shades.',
    mat: ['One colour, white and black paint', 'Palette', 'Brushes', 'Paper'], rel: ['hue-value-sat', 'value-scale', 'colour-wheel'] },
  { id: 'neutrals', s: 'colour', n: 'Mixing neutrals and greys', sum: 'Browns and greys mixed from complementary colours.', lvl: 2, mins: 30, ill: 'neutrals',
    what: 'Mixing complementary colours (red and green, blue and orange, yellow and violet) makes rich browns and greys called neutrals. Unlike greys made from black and white, they’re lively and sit in harmony with the other colours in a painting.',
    why: 'Most natural colours are muted. Mixing neutrals from complements makes paintings look natural and unified.',
    steps: ['Choose a complementary pair.', 'Mix them in different proportions: mostly one, half and half, mostly the other.', 'Add white to each mix to see its true colour.', 'Label each recipe.', 'Use these neutrals for shadows, backgrounds and earthy subjects.'],
    tips: ['Ultramarine and burnt sienna make a beautiful range of greys.', 'A neutral next to a pure colour makes the pure colour glow.', 'Lean a neutral warm or cool by changing the proportions.'],
    mistakes: ['Using black for every shadow.', 'Adding a third colour and turning the mix to mud.', 'Not testing with white.'],
    ex: 'Mix ten browns and greys from complements and label each recipe.',
    kids: 'Mix mud colours on purpose and give them funny names.',
    adults: 'Paint a whole picture with a limited palette, such as three primaries plus burnt sienna.',
    mat: ['Paints including complementary pairs', 'White', 'Palette', 'Paper'], rel: ['colour-wheel', 'temperature', 'skin-tones'] },
  { id: 'skin-tones', s: 'colour', n: 'Mixing skin tones', sum: 'Mixing the full range of skin colours accurately and respectfully.', lvl: 2, mins: 40, ill: 'skin',
    what: 'Skin tones are mixed rather than squeezed from one tube. A useful base is red, yellow and white, deepened with burnt umber or burnt sienna and adjusted with a little blue or green. Every skin has warmer and cooler areas, highlights and shadows.',
    why: 'Students want to paint the people they know, including themselves. Mixing a wide range of skin tones accurately and respectfully is an important skill.',
    steps: ['Start with a little red and yellow to make an orange.', 'Add white for lighter skin, or burnt umber or sienna for deeper skin.', 'Adjust: a touch of blue or green calms a mix that’s too orange.', 'Mix a lighter version for highlights and a deeper, cooler one for shadows.', 'Test swatches on paper next to the reference.', 'Notice warm areas (cheeks, nose, ears) and cooler areas (jaw, eye sockets).'],
    tips: ['Hold swatches right next to the photo to compare.', 'No skin is one flat colour.', 'Name mixes by their recipe, never as “skin colour”.'],
    mistakes: ['Lightening deep skin tones with white, which looks chalky. Use lighter, warmer browns instead.', 'Flat, single-colour faces.', 'Mixes that are too pink or too orange.'],
    ex: 'Make a skin tone chart with recipes, then paint a small portrait study.',
    kids: 'With everyone’s agreement, mix a tone to match each student’s hand and make a “we are all colours” display.',
    adults: 'Paint a portrait study with a limited palette, such as yellow ochre, cadmium red, ultramarine and white.',
    mat: ['Red, yellow, blue, white and burnt umber or burnt sienna paints', 'Palette', 'Paper', 'Portrait references'], rel: ['neutrals', 'face', 'temperature'] },

  /* ---------- materials and media ---------- */
  { id: 'graphite', s: 'media', n: 'Graphite pencils', sum: 'Choosing and using pencil grades from H to B.', lvl: 1, mins: 20, ill: 'grades',
    what: 'Graphite pencils are graded by hardness. H pencils are harder and lighter (6H is very light and crisp), B pencils are softer and darker (8B is very dark and smudgy), and HB sits in the middle. Each grade suits different jobs.',
    why: 'Using a range of grades gives a full range of values without pressing hard, and keeps drawings clean.',
    steps: ['Make a swatch of each grade at normal pressure.', 'Use H pencils for light construction lines and pale values.', 'Use HB to 2B for general drawing.', 'Use 4B to 8B for the darks, building them in layers.', 'Use the side of the lead for broad tone and the tip for lines.', 'Sharpen with a craft knife for a long point, or with a good sharpener.'],
    tips: ['Don’t try to make darks with an H pencil: it shines and dents the paper.', 'Graphite shines at its darkest; charcoal goes darker.', 'Store pencils so their tips don’t break.'],
    mistakes: ['Pressing hard with one pencil for everything.', 'Using very soft pencils first, which smudges across the page.', 'Blunt points for detail.'],
    ex: 'Make a grade chart from 6H to 8B, then shade a sphere with three grades.',
    kids: 'HB and 2B are plenty. Let them feel the difference with a soft-or-hard test.',
    adults: 'Build a kit of 2H, HB, 2B, 4B, 6B and a mechanical pencil for detail.',
    mat: ['Pencils 2H to 8B', 'Sharpener or craft knife', 'Kneaded and plastic erasers', 'Cartridge paper'], rel: ['value-scale', 'blending', 'hatching'] },
  { id: 'charcoal', s: 'media', n: 'Charcoal', sum: 'Vine, compressed and pencil charcoal for bold tone.', lvl: 1, mins: 30, ill: 'charcoal',
    what: 'Charcoal comes as vine or willow sticks (light, soft and easy to erase), compressed sticks (dense, rich black) and charcoal pencils (for controlled lines). It makes bold, expressive drawings with deep darks, quickly.',
    why: 'It encourages working big and loose, thinking in masses of tone rather than outlines, and it’s very forgiving.',
    steps: ['Start with vine charcoal to block in the big shapes lightly.', 'Use the side of the stick for broad tone and the tip for lines.', 'Smudge with tissue or fingers for soft areas.', 'Lift out lights with a kneaded eraser.', 'Add the darkest darks with compressed charcoal.', 'Use a charcoal pencil for details.', 'Fix the drawing with fixative in a well-ventilated place.'],
    tips: ['Work standing at an easel for big, free marks.', 'Keep baby wipes handy.', 'Use paper with some tooth so the charcoal grips.'],
    mistakes: ['Starting with compressed charcoal, which is hard to erase.', 'Drawing small and tight.', 'Resting hands on the drawing.'],
    ex: 'Make a sampler of vine, compressed and pencil charcoal, smudged and lifted, then do a quick still life.',
    kids: 'Draw a big, dramatic storm or dinosaur, then smudge the sky.',
    adults: 'Do timed figure or still life studies in charcoal to loosen up.',
    mat: ['Vine or willow charcoal', 'Compressed charcoal', 'Charcoal pencils', 'Kneaded eraser', 'Tissue', 'Cartridge or newsprint paper', 'Fixative'], rel: ['subtractive', 'chiaroscuro', 'gesture'] },
  { id: 'pen-ink', s: 'media', n: 'Pen and ink', sum: 'Confident line, value and texture in ink.', lvl: 2, mins: 30, ill: 'ink',
    what: 'Pen and ink drawing uses fineliners, technical pens, brush pens or dip pens. Ink can’t be erased, so value is built with line techniques (hatching, cross-hatching, stippling, scribbling) and line weight.',
    why: 'It builds confidence and decision-making, gives crisp, graphic results and suits illustration, urban sketching and comics.',
    steps: ['Plan the drawing lightly in pencil, or draw straight in pen to build confidence.', 'Ink the main contours with varied line weight.', 'Choose a shading method and build the values gradually.', 'Leave white paper for the highlights.', 'Let the ink dry completely before erasing any pencil.'],
    tips: ['Hold technical pens upright; tilt brush pens for thick and thin lines.', 'Turn mistakes into texture or part of the design.', 'Rest your hand on scrap paper to avoid smudging.'],
    mistakes: ['Pressing hard on fineliners, which damages the tip.', 'Erasing before the ink is dry.', 'Outlining everything with the same weight.'],
    ex: 'Draw a leaf straight in pen with no pencil first, then shade an object using hatching.',
    kids: 'Draw doodle monsters with felt-tip pens and fill them with patterns.',
    adults: 'Try urban sketching: a café or street in pen, perhaps with a watercolour wash.',
    mat: ['Fineliners 0.05 to 0.8', 'Brush pen', 'Pencil and eraser', 'Smooth paper'], rel: ['hatching', 'stippling', 'line-weight'] },
  { id: 'ink-wash', s: 'media', n: 'Ink wash', sum: 'Painting values with diluted ink.', lvl: 2, mins: 30, ill: 'inkwash',
    what: 'Ink wash uses ink diluted with water to paint values with a brush, from pale grey to black. It’s used in East Asian brush painting and in Western sketching, often combined with pen lines.',
    why: 'It’s a fast way to block in values and makes atmospheric, flowing effects.',
    steps: ['Prepare three or four dishes of ink: very diluted, light, medium and full strength.', 'Test the values on scrap paper.', 'Paint the lightest areas first with the palest wash.', 'Let it dry, then add the middle values.', 'Add the darks last.', 'Add pen details once everything is dry.'],
    tips: ['Use watercolour paper so it doesn’t buckle.', 'For soft edges, paint into damp areas; for hard edges, wait until dry.', 'Waterproof ink lets you layer washes over pen lines.'],
    mistakes: ['Starting with the darks.', 'Fiddling with wet areas, which leaves blooms.', 'Pen lines that aren’t waterproof and bleed.'],
    ex: 'Paint a three-value ink wash study of a cup and a piece of fruit.',
    kids: 'Paint a misty mountain scene with three grey washes.',
    adults: 'Try a bamboo or landscape study inspired by East Asian brush painting.',
    mat: ['Black ink (Indian ink or sumi)', 'Round brushes', 'Small dishes', 'Water', 'Watercolour paper'], rel: ['washes', 'pen-ink', 'value-scale'] },
  { id: 'coloured-pencil', s: 'media', n: 'Coloured pencil: layering and burnishing', sum: 'Building rich colour in light layers.', lvl: 2, mins: 40, ill: 'cplayer',
    what: 'Coloured pencils are translucent, so colours mix by layering one over another on the paper. Burnishing presses the final layers firmly, or uses a colourless blender, to fill the paper’s texture for a smooth, shiny finish.',
    why: 'Layering gives depth and richness that a single pencil can’t, and it teaches how colours mix optically.',
    steps: ['Lightly outline the drawing with a pencil in a matching colour.', 'Lay down the lightest colours first with light pressure.', 'Add layers of other colours, building gradually.', 'Shade with complementary or darker colours rather than black.', 'Burnish the final layers with firm pressure, a white pencil or a colourless blender.', 'Add details and sharp highlights last.'],
    tips: ['Many light layers beat one heavy one.', 'Keep pencils sharp.', 'Plan the highlights early and leave the paper white for them.'],
    mistakes: ['Pressing hard early, which fills the paper so it won’t take more layers.', 'Shading with black, which dulls the colours.', 'Graphite outlines showing through.'],
    ex: 'Make a layering chart, then draw a cherry or a gumnut and burnish it to a shine.',
    kids: 'Colour rainbow fruit by layering two colours each, then try burnishing a small spot.',
    adults: 'Draw a realistic piece of fruit or a feather using at least five colours in each area.',
    mat: ['Artist-quality coloured pencils', 'Colourless blender', 'Smooth paper', 'Sharpener'], rel: ['colour-wheel', 'blending', 'temperature'] },
  { id: 'pastels', s: 'media', n: 'Soft and oil pastels', sum: 'Bold colour, blending and scratching back.', lvl: 1, mins: 30, ill: 'pastel',
    what: 'Soft (chalk) pastels are powdery and blend easily with fingers or tissue, and work best on textured paper. Oil pastels are waxy, rich and bright, and can be layered and scratched into, which is called sgraffito.',
    why: 'Pastels give bright, painterly results with no drying time, and they’re great for building confidence with colour.',
    steps: ['Choose textured paper, such as pastel paper or coloured card.', 'Block in big areas with the side of the pastel.', 'Blend soft pastels with fingers or tissue; layer oil pastels.', 'Add lighter colours on top for highlights.', 'For sgraffito, layer a dark oil pastel over a bright one, then scratch lines through it.', 'Fix soft pastel work, or store it under glassine paper.'],
    tips: ['Dark coloured paper gives dramatic results.', 'Keep a cloth handy for each hand.', 'Don’t blend everything; leave some strokes showing.'],
    mistakes: ['Over-blending into mud.', 'Smooth paper that won’t hold the layers.', 'Pressing too hard too early with oil pastels.'],
    ex: 'Make an oil pastel sunset with scratched-in details, or a soft pastel landscape.',
    kids: 'Draw with oil pastel, then paint over it with watercolour to see the resist.',
    adults: 'Make a soft pastel landscape on toned paper.',
    mat: ['Soft pastels', 'Oil pastels', 'Pastel or coloured paper', 'Tissue', 'Toothpick or scratching tool', 'Fixative'], rel: ['colour-wheel', 'blending', 'temperature'] },
  { id: 'washes', s: 'media', n: 'Watercolour washes', sum: 'Flat, graded and variegated washes.', lvl: 1, mins: 30, ill: 'wash',
    what: 'Washes are the foundation of watercolour. A flat wash is one even colour, a graded wash goes from dark to light, and a variegated wash blends one colour into another. All of them are painted by keeping a wet edge moving down the paper.',
    why: 'Washes are used for skies, backgrounds and large shapes, and controlling them builds confidence with water and paint.',
    steps: ['Tape the paper down and tilt the board slightly.', 'Mix more paint than you think you’ll need.', 'Load a large brush and paint a horizontal stroke across the top.', 'Paint the next stroke so it catches the bead of wet paint at the bottom of the first.', 'For a graded wash, add more water to the mix with each stroke.', 'For a variegated wash, change to a second colour partway down.', 'Pick up the last bead with a damp brush and let it dry flat.'],
    tips: ['Keep the board tilted so the bead flows down.', 'Don’t go back into a drying wash.', 'Use 300 gsm watercolour paper so it doesn’t buckle.'],
    mistakes: ['Running out of paint halfway.', 'Fiddling as the wash dries, which causes blooms.', 'Thin paper that buckles.'],
    ex: 'Paint flat, graded and variegated swatches, then a sunset sky.',
    kids: 'Paint a graded sky and stick on a black paper silhouette of a city or trees.',
    adults: 'Practise washes on half sheets, then use one as the sky of a landscape.',
    mat: ['Watercolour paints', 'Large round or flat brush', 'Watercolour paper (300 gsm)', 'Masking tape', 'Board', 'Water jars'], rel: ['wet-in-wet', 'skies', 'ink-wash'] },
  { id: 'wet-in-wet', s: 'media', n: 'Wet-in-wet and wet-on-dry', sum: 'Soft blooms versus crisp edges in watercolour.', lvl: 2, mins: 30, ill: 'wet',
    what: 'Wet-in-wet means painting onto wet paper or wet paint, so the colours spread and blend with soft edges. Wet-on-dry means painting onto dry paper, which gives crisp, controlled edges. Most watercolours use both.',
    why: 'Knowing when to use each one gives control over edges, which is the heart of watercolour.',
    steps: ['Wet a shape with clean water until it glistens evenly.', 'Drop in colour and watch it spread, tilting the paper to guide it.', 'Drop in a second colour and let them mix on the paper.', 'Let it dry completely.', 'Paint crisp shapes on top, wet-on-dry.', 'Compare the two kinds of edge.'],
    tips: ['The wetter the paper, the further the paint spreads.', 'Drop in stronger paint than you think; it lightens as it dries.', 'A hairdryer speeds up drying between layers.'],
    mistakes: ['Paper so wet that the paint floods.', 'Adding wetter paint into a drying area, which makes cauliflower-shaped blooms.', 'Only ever using one approach.'],
    ex: 'Paint a soft wet-in-wet background, let it dry, then add crisp wet-on-dry leaves on top.',
    kids: 'Paint galaxies or underwater scenes wet-in-wet and sprinkle on salt.',
    adults: 'Paint loose flowers with wet-in-wet petals and wet-on-dry stems.',
    mat: ['Watercolour paints', 'Round brushes', 'Watercolour paper', 'Spray bottle'], rel: ['washes', 'wc-textures', 'skies'] },
  { id: 'wc-textures', s: 'media', n: 'Watercolour textures', sum: 'Salt, lifting, wax resist and masking fluid.', lvl: 1, mins: 30, ill: 'wctex',
    what: 'Watercolour can be textured with simple tricks. Salt sprinkled into wet paint makes starry speckles, lifting with a tissue or damp brush removes paint for clouds and highlights, and wax crayon or masking fluid resists the paint to keep lines white.',
    why: 'Textures add interest and are a fun way to explore how watercolour behaves.',
    steps: ['Salt: paint a strong wash, sprinkle salt while it’s still shiny, let it dry, then brush the salt off.', 'Lifting: blot wet paint with scrunched tissue, or re-wet dry paint and lift it with a clean brush.', 'Wax resist: draw with a white crayon or a candle, then paint over the top.', 'Masking fluid: paint it on, let it dry, paint over it, then rub it off once everything is dry.'],
    tips: ['Salt works best on paint that’s wet but not soaking.', 'Use an old brush for masking fluid and wash it with soap straight away.', 'Some pigments lift more easily than others.'],
    mistakes: ['Salt on paint that’s too dry (no effect) or too wet (blotches).', 'Removing masking fluid before the paint is dry.', 'Using so many tricks that they take over.'],
    ex: 'Paint a night sky or an underwater scene using salt, wax resist and lifting.',
    kids: 'Write secret messages in white crayon and reveal them with paint.',
    adults: 'Use masking fluid to save highlights in a landscape or still life.',
    mat: ['Watercolour paints and paper', 'Table or rock salt', 'White crayon or a candle', 'Masking fluid', 'Tissues'], rel: ['wet-in-wet', 'washes', 'water'] },
  { id: 'acrylic', s: 'media', n: 'Acrylic: blocking in, layering and glazing', sum: 'Building a painting from big shapes to details.', lvl: 1, mins: 45, ill: 'acrylic',
    what: 'Acrylic paint dries quickly and can be used thick, or thinned with water. A reliable method is to block in big flat shapes first, build up light and shadow in layers, and finish with details and highlights. Thin, transparent layers called glazes can adjust colours on top.',
    why: 'Working from big to small gives a painting structure and stops students getting lost in details. Acrylic’s fast drying makes layering easy.',
    steps: ['Tone the canvas with a thin wash of a middle colour.', 'Sketch the main shapes with a thin brush.', 'Block in big, flat areas of colour, ignoring details.', 'Add the shadows and mid-tones.', 'Add the lighter areas and details.', 'Add highlights last.', 'Glaze with thinned paint or medium to adjust colours.'],
    tips: ['Keep paint workable with a spray bottle, or a damp sponge under the palette.', 'Use bigger brushes for longer than feels natural.', 'Acrylic dries a little darker, so mix slightly lighter.'],
    mistakes: ['Adding details too early.', 'Letting paint dry in the brushes.', 'Using thick paint for every layer.'],
    ex: 'Paint a simple apple in three stages: block in, light and shadow, then highlights and details.',
    kids: 'Paint a bold animal in flat colour on canvas board, then add patterns.',
    adults: 'Paint a still life from life over two sessions.',
    mat: ['Acrylic paints', 'Flat and round brushes', 'Canvas or canvas board', 'Palette and spray bottle', 'Water jars', 'Rags'], rel: ['dry-brush', 'impasto', 'tints-shades'] },
  { id: 'dry-brush', s: 'media', n: 'Dry brush and scumbling', sum: 'Broken, textured strokes with very little paint.', lvl: 2, mins: 25, ill: 'drybrush',
    what: 'Dry brush uses a brush with very little paint and almost no water, dragged lightly so the paint only catches the raised texture of the paper or canvas. Scumbling scrubs a thin, broken layer of lighter paint over a darker one.',
    why: 'Both create texture, such as grass, wood, rock and hair, and soften or brighten areas without covering them completely.',
    steps: ['Load the brush with paint, then wipe most of it off on a rag.', 'Hold the brush low and drag it lightly across the surface.', 'Build texture in a few passes.', 'To scumble, scrub a light colour over a dry dark area with small circular strokes.', 'Leave the broken texture showing.'],
    tips: ['Stiff bristle brushes work best.', 'Splay the bristles for grass and hair.', 'Only use it over dry layers.'],
    mistakes: ['Too much paint, so the strokes come out solid.', 'Pressing hard.', 'Covering the whole picture in texture.'],
    ex: 'Paint grass and weathered wood using dry brush.',
    kids: 'Make a fluffy animal with an old toothbrush or dry brush strokes.',
    adults: 'Use scumbling to add atmosphere and glow to a landscape.',
    mat: ['Acrylic or oil paint', 'Stiff bristle brushes', 'Rags', 'Canvas or textured paper'], rel: ['acrylic', 'textures', 'trees'] },
  { id: 'impasto', s: 'media', n: 'Impasto and palette knife', sum: 'Thick, textured paint applied with a knife or brush.', lvl: 2, mins: 30, ill: 'impasto',
    what: 'Impasto is paint applied so thickly that the strokes stand up from the surface. It’s often applied with a palette knife, which spreads, scrapes and sculpts the paint into bold, expressive textures.',
    why: 'Impasto catches real light, adding energy and physical texture, and the knife encourages bold, loose decisions.',
    steps: ['Use thick paint, or mix texture paste or heavy gel into acrylics.', 'Scoop paint onto the underside of the knife.', 'Spread it like butter on toast, pressing and lifting.', 'Use the edge of the knife for thin lines and the tip for small dabs.', 'Lay strokes in the direction of the form: across petals, along waves.', 'Let thick layers dry fully, which can take a day.'],
    tips: ['Don’t overmix colours on the canvas; let streaks of colour show.', 'Combine impasto in the foreground with thin paint in the background for depth.', 'Clean the knife between colours.'],
    mistakes: ['Overworking, which flattens the texture.', 'Using impasto everywhere.', 'Using too little paint.'],
    ex: 'Paint a textured flower or seascape with a palette knife.',
    kids: 'Use plastic knives and thick paint to make textured sunflowers.',
    adults: 'Paint a small landscape entirely with a palette knife.',
    mat: ['Heavy-body acrylic paint', 'Palette knives', 'Texture paste or heavy gel (optional)', 'Canvas board'], rel: ['acrylic', 'textures', 'dry-brush'] },
  { id: 'collage', s: 'media', n: 'Collage and mixed media', sum: 'Building pictures from paper, paint and found materials.', lvl: 1, mins: 40, ill: 'collage',
    what: 'Collage builds a picture by cutting or tearing paper and other materials and gluing them down. Mixed media combines collage with paint, pastel, ink or drawing on top.',
    why: 'It’s accessible to every age and ability, encourages experiments with colour, texture and shape, and uses cheap or recycled materials.',
    steps: ['Collect papers: magazines, painted paper, tissue, wrapping paper, maps.', 'Plan a simple design with big shapes.', 'Tear or cut the background pieces first and glue them down.', 'Add the middle and foreground shapes on top.', 'Add details with paint, pastel or pen.', 'Seal with a thin layer of glue or matte medium.'],
    tips: ['Torn edges look softer and more natural; cut edges look crisp.', 'Make your own patterned paper by painting and printing on scrap paper.', 'Use contrast in colour or pattern to make shapes stand out.'],
    mistakes: ['Too many tiny pieces, which looks busy.', 'Wet glue wrinkling thin paper.', 'Losing the main shapes under detail.'],
    ex: 'Make a torn-paper animal or landscape, then add details in pen or pastel.',
    kids: 'Make an Eric Carle-style animal from painted papers.',
    adults: 'Make a mixed-media piece with layered collage, paint and drawing.',
    mat: ['Assorted papers', 'Scissors', 'Glue stick or PVA glue', 'Paint and pastels', 'Heavy paper or card'], rel: ['printmaking', 'schemes', 'pattern'] },
  { id: 'printmaking', s: 'media', n: 'Simple printmaking', sum: 'Foam, block and stamp printing.', lvl: 1, mins: 45, ill: 'print',
    what: 'In relief printmaking, a design is carved or pressed into a surface, ink is rolled over it, and paper is pressed on top to print it. Polystyrene foam sheets are an easy, safe starting point; lino and rubber blocks come next.',
    why: 'Printing lets students make multiples, experiment with colour and learn to think in reverse and in positive and negative shapes.',
    steps: ['Draw a design on paper the size of the foam sheet. Remember that the print comes out reversed, especially letters.', 'Transfer it by pressing firmly into the foam with a blunt pencil.', 'Roll a thin, even layer of block printing ink over the foam with a brayer.', 'Place paper on top and rub firmly with a clean roller or the back of a spoon.', 'Peel off the paper to reveal the print.', 'Re-ink and print again, trying different colours of ink and paper.'],
    tips: ['Press lines deep enough to stay white, but don’t cut through the foam.', 'Thin, even ink gives crisp prints.', 'Number and sign prints like a professional: 1/5, 2/5…'],
    mistakes: ['Letters that come out backwards.', 'Too much ink, which fills the lines.', 'Paper sliding during rubbing.'],
    ex: 'Print a foam plate of a leaf or a fish three times in different colours.',
    kids: 'Make prints from foam, sponges, vegetables or found objects.',
    adults: 'Try lino printing with safety cutters, or a two-colour reduction print.',
    mat: ['Polystyrene foam sheets', 'Blunt pencil', 'Water-based block printing ink', 'Brayer (roller)', 'Inking tray', 'Paper'], rel: ['collage', 'notan', 'pattern'] },

  /* ---------- subjects ---------- */
  { id: 'face', s: 'subj', n: 'Face proportions', sum: 'Where the eyes, nose, mouth and ears sit.', lvl: 2, mins: 40, ill: 'face',
    what: 'Most faces follow general proportions: the eyes sit about halfway down the head, the nose ends about halfway between the eyes and the chin, the mouth sits about a third of the way from the nose to the chin, and the ears line up between the brow and the bottom of the nose. Everyone differs a little, which is what makes a likeness.',
    why: 'Most beginners place the eyes far too high. Learning the guidelines fixes that instantly, and studying how each face differs builds observation.',
    steps: ['Draw an egg shape for the head, wider at the top.', 'Draw a vertical centre line and a horizontal line halfway down for the eyes.', 'Space the eyes about one eye-width apart.', 'Mark the bottom of the nose halfway between the eye line and the chin.', 'Mark the mouth about a third of the way from the nose to the chin.', 'Place the ears between the brow line and the nose line.', 'Add the hairline about a third of the way between the eyebrows and the top of the head, and draw the hair above the skull, not on it.'],
    tips: ['The corners of the mouth often line up with the centres of the eyes.', 'The bottom of the nose is about as wide as the gap between the eyes.', 'Then compare with your real subject and adjust; the differences are the likeness.'],
    mistakes: ['Eyes too high, which cuts off the top of the skull.', 'Hair drawn flat on the head.', 'Features too large for the face.'],
    ex: 'Draw a front-on face with guidelines, then draw the same guidelines over a photo of a face and compare.',
    kids: 'Make a guideline face, then turn it into a self-portrait with mirrors.',
    adults: 'Measure features on photos of different people and note how they vary from the guide.',
    mat: ['HB and 2B pencils', 'Eraser', 'Mirror or photos'], rel: ['eyes', 'sighting', 'skin-tones'] },
  { id: 'eyes', s: 'subj', n: 'Drawing eyes', sum: 'Lids, iris, highlight and the shadow of the lid.', lvl: 2, mins: 35, ill: 'eye',
    what: 'An eye is a ball set in a socket and wrapped by the eyelids. The upper lid is thicker and casts a shadow on the eyeball, the iris is partly covered by the upper lid, the highlight sits over the pupil and iris, and the lower lid has a visible thickness.',
    why: 'Eyes are usually the focal point of a portrait. Drawing them as forms, not symbols, makes faces come alive.',
    steps: ['Draw the almond shape lightly, remembering it’s a ball under the lids.', 'Draw the iris as a circle partly hidden by the upper lid.', 'Add the pupil, and mark the highlight so you keep it white.', 'Shade the iris with lines radiating from the pupil, darker at the outer edge.', 'Shade the eyeball near the upper lid, where the lid casts its shadow. The white of the eye is never pure white.', 'Draw the upper lid’s crease and thickness, and the thickness of the lower lid.', 'Add lashes last, as curved, tapering strokes in clumps.'],
    tips: ['The highlight should overlap the pupil and iris, and match the light direction in both eyes.', 'Look for the tear duct in the inner corner.', 'Draw both eyes at the same time to keep them matching.'],
    mistakes: ['Showing the whole iris, which makes a startled stare.', 'Pure white eyeballs.', 'Every lash drawn individually and stiffly.'],
    ex: 'Fill a page with eye shapes from different angles, then shade one eye fully from a photo.',
    kids: 'Draw big cartoon eyes, then compare them with real eyes in a mirror.',
    adults: 'Draw eyes from three angles: front, three-quarter and profile.',
    mat: ['HB, 2B and 4B pencils', 'Kneaded eraser', 'Blending stump', 'Mirror or photos'], rel: ['face', 'light-form', 'blending'] },
  { id: 'hands', s: 'subj', n: 'Hands', sum: 'A palm box, fingers in segments and the knuckle arc.', lvl: 3, mins: 40, ill: 'hand',
    what: 'Hands are easier when built from simple shapes: a flattened box for the palm, three segments for each finger getting shorter towards the tip, and a wedge for the thumb. The knuckles form an arc, not a straight line.',
    why: 'Hands are expressive and famously tricky. Construction gives students a reliable way in.',
    steps: ['Draw the palm as a slightly tapered, flat box.', 'Mark the knuckles as a gentle arc across the top of the palm.', 'Draw each finger as three cylinder segments, shorter towards the tip.', 'Add the thumb from the side of the palm, as a wedge with two segments.', 'Refine the outline, looking at the real hand.', 'Add creases and nails last, lightly.'],
    tips: ['The middle finger is the longest; the fingers fan slightly apart.', 'Use your own hand as a model in a mirror.', 'Draw the gesture of the hand first.'],
    mistakes: ['Fingers all the same length, like sausages.', 'A straight row of knuckles.', 'Too many creases and wrinkles.'],
    ex: 'Draw your hand in five poses, first as shapes, then refined.',
    kids: 'Trace a hand, then turn it into an animal or a tree.',
    adults: 'Do timed studies of hands holding objects: a cup, a pencil, a phone.',
    mat: ['Pencils', 'Mirror', 'Sketchbook'], rel: ['shapes', 'foreshortening', 'gesture'] },
  { id: 'figure', s: 'subj', n: 'Figure proportions', sum: 'The body measured in head-heights.', lvl: 2, mins: 40, ill: 'figure',
    what: 'Artists measure the body in head-heights. An adult is usually about seven and a half to eight heads tall, with the hips at about halfway. Children’s heads are bigger in proportion: a small child is about four to five heads tall.',
    why: 'Proportions give students a framework for drawing believable people from life or imagination.',
    steps: ['Mark a top and bottom line and divide the space into eight equal parts.', 'Draw the head in the first part.', 'Place the chest at about two heads, the waist at three and the hips at four.', 'Place the knees at about six heads and the feet at eight.', 'Build the body with simple shapes: an egg for the ribcage, a box for the hips, cylinders for the limbs.', 'Check that the elbows line up with the waist and the wrists with the hips.'],
    tips: ['Real people vary; use the guide, then observe.', 'Shoulders are about two heads wide on adults.', 'Use a wooden mannequin to explore poses.'],
    mistakes: ['A head that’s too big for an adult figure.', 'Arms too short (fingertips reach mid-thigh).', 'A stiff, straight-on pose.'],
    ex: 'Draw an eight-head figure standing, then the same figure in an action pose.',
    kids: 'Draw stick figures with joints, then add shapes: a “sausage person”.',
    adults: 'Draw from a model or pose photos, measuring in head-heights.',
    mat: ['Pencils', 'Ruler', 'Wooden mannequin (optional)', 'Pose photos'], rel: ['gesture', 'foreshortening', 'shapes'] },
  { id: 'animals', s: 'subj', n: 'Animals from shapes', sum: 'Building animals from circles and ovals.', lvl: 1, mins: 35, ill: 'animal',
    what: 'Most animals can be built from simple shapes: a circle for the head, ovals for the chest and hips, and lines or cylinders for the legs, all joined along a line of movement. The outline and details go on top.',
    why: 'Shapes give accurate proportions quickly and let students draw animals in any pose.',
    steps: ['Draw a line of action for the spine and tail.', 'Add a circle for the head and ovals for the chest and hips.', 'Add the neck and connect the body.', 'Draw the legs as simple lines, noting where the joints bend.', 'Add ears, tail and features.', 'Refine the outline and add fur direction or patterns.'],
    tips: ['Look at where an animal’s legs bend: many “knees” are actually ankles.', 'Fur follows the form; draw it in the direction it grows.', 'Photos of pets are great references.'],
    mistakes: ['Starting with the outline and eyes.', 'Legs too thin or too straight.', 'Drawing every hair.'],
    ex: 'Draw a cat, a dog and a bird, each built from circles and ovals.',
    kids: 'Draw Australian animals (kookaburra, koala, wombat) from shapes.',
    adults: 'Do gesture studies of animals moving from video, then a finished study.',
    mat: ['Pencils', 'Eraser', 'Animal references'], rel: ['shapes', 'gesture', 'textures'] },
  { id: 'trees', s: 'subj', n: 'Trees and foliage', sum: 'Masses of light and shadow, not single leaves.', lvl: 1, mins: 35, ill: 'tree',
    what: 'Trees are best drawn as big masses, or clumps, of foliage with light and shadow sides, rather than individual leaves. The trunk tapers as it branches, and gaps in the foliage let the sky show through.',
    why: 'Thinking in masses makes trees look natural and solid in any medium, and it’s a key landscape skill.',
    steps: ['Draw the trunk and main branches, tapering as they divide.', 'Block in the foliage as a few large clumps.', 'Decide on the light direction, then shade each clump darker on its shadow side and underneath.', 'Add a few sky holes through the foliage.', 'Add texture marks along the edges of the clumps.', 'Add a cast shadow on the ground.'],
    tips: ['Each tree species has its own silhouette; observe it.', 'Eucalyptus trees have open, drooping foliage and pale, smooth trunks.', 'Squint to find the big masses.'],
    mistakes: ['Lollipop trees: a stick with a round blob.', 'Drawing every leaf.', 'Branches that don’t taper.'],
    ex: 'Draw three trees, a gum, a pine and a bushy tree, each as masses of light and shadow.',
    kids: 'Paint trees with sponges for foliage and straws to blow ink branches.',
    adults: 'Sketch trees outdoors in pencil, then in watercolour.',
    mat: ['Pencils or paint', 'Sponge (optional)', 'Paper'], rel: ['atmospheric', 'dry-brush', 'textures'] },
  { id: 'skies', s: 'subj', n: 'Skies and clouds', sum: 'Gradients, lit tops and shaded bases.', lvl: 1, mins: 30, ill: 'sky',
    what: 'A clear sky is usually deeper in colour at the top and paler near the horizon. Clouds are three-dimensional: lit on top and shaded underneath, and smaller, flatter and closer together near the horizon because of perspective.',
    why: 'The sky sets the light and mood of a landscape, and it’s a satisfying way to practise gradients and soft edges.',
    steps: ['Paint or shade the sky as a gradient from top to horizon.', 'Leave or lift out the cloud shapes.', 'Shade the undersides of the clouds with a soft grey or violet.', 'Keep cloud tops bright, with crisp edges where they meet blue sky.', 'Make clouds smaller and flatter as they near the horizon.'],
    tips: ['Watercolour wet-in-wet makes soft clouds; lift with tissue for highlights.', 'Clouds have both soft and hard edges.', 'Photograph skies at different times of day for reference.'],
    mistakes: ['Clouds the same size all over the sky.', 'Outlined clouds.', 'An even sky with no gradient.'],
    ex: 'Paint three small skies: clear, cloudy and stormy.',
    kids: 'Make cotton-wool cloud collages, then paint sunset skies.',
    adults: 'Paint a sky study every day for a week from life.',
    mat: ['Watercolour, acrylic or pastel', 'Tissue', 'Paper'], rel: ['washes', 'wet-in-wet', 'atmospheric'] },
  { id: 'water', s: 'subj', n: 'Water and reflections', sum: 'Reflections drop straight down; ripples break them up.', lvl: 2, mins: 35, ill: 'water',
    what: 'Still water reflects like a mirror, with reflections falling straight down below objects, slightly darker than the objects themselves. Moving water breaks reflections into horizontal bands and wavy shapes.',
    why: 'Water is a favourite subject, and understanding reflections makes it look convincing.',
    steps: ['Draw the object and the waterline.', 'Measure the reflection straight down from where the object meets the water.', 'Make the reflection slightly darker and less detailed than the object.', 'Break it with horizontal ripple lines or gaps.', 'Add light streaks across the water surface.', 'For waves, show the light top surfaces and darker faces.'],
    tips: ['Reflections are vertical even if the light comes from the side.', 'Keep the waterline horizontal.', 'Moving water: simplify the reflection into wobbly shapes.'],
    mistakes: ['Reflections slanting sideways.', 'A reflection as bright and detailed as the object.', 'Vertical brushstrokes for the water surface.'],
    ex: 'Paint a boat or a jetty with its reflection in still water.',
    kids: 'Fold a painting while wet to make a mirror reflection.',
    adults: 'Paint the same scene in still and in rippled water.',
    mat: ['Watercolour or acrylic', 'Brushes', 'Paper'], rel: ['wc-textures', 'skies', 'washes'] },
  { id: 'still-life', s: 'subj', n: 'Setting up a still life', sum: 'Choosing, arranging and lighting objects.', lvl: 1, mins: 45, ill: 'stilllife',
    what: 'A still life is an arrangement of objects drawn or painted from life. A good set-up uses objects of different heights, shapes and textures, overlapping, with one strong light source.',
    why: 'Still life lets students practise observation, proportion, light and composition at their own pace, from real objects.',
    steps: ['Choose three to five objects with different heights, shapes and textures.', 'Arrange them on a cloth, overlapping some, with odd numbers and uneven spacing.', 'Light them from one side with a lamp.', 'Make thumbnails to choose the view.', 'Measure and draw the big shapes first.', 'Shade from dark to light, then add textures and details.'],
    tips: ['Overlap creates depth; avoid objects in a row.', 'Choose objects with meaning for the students.', 'Mark the positions with tape so the set-up can be rebuilt.'],
    mistakes: ['Objects lined up like a shop shelf.', 'Flat, even lighting.', 'Starting with details before the big shapes.'],
    ex: 'A measured, shaded drawing of a three-object still life.',
    kids: 'Draw a fruit bowl, then do a fantasy version with silly objects.',
    adults: 'Do a still life in three media over three weeks.',
    mat: ['Objects and fabric', 'A lamp', 'Pencils or paint', 'Paper'], rel: ['light-form', 'cast-shadows', 'thirds'] },
  { id: 'drapery', s: 'subj', n: 'Drapery and folds', sum: 'How cloth hangs and folds.', lvl: 3, mins: 40, ill: 'drapery',
    what: 'Cloth falls into a few kinds of folds: pipe folds hanging from a point, zigzag folds where fabric bends, spiral folds around a limb, and soft folds where it lies. Each fold has a lit top, a shadow side and a cast shadow.',
    why: 'Drapery appears in still lifes and figures and is an excellent study in light and form.',
    steps: ['Pin a cloth from one or two points.', 'Find the main folds and their direction from the pins.', 'Draw them as long lines and simple tubes.', 'Shade each fold: light on top, shadow on the side, darkest in the deepest creases.', 'Add the softer folds and edges last.'],
    tips: ['Plain cloth is easier than patterned.', 'Squint to see the big shapes of light and shadow.', 'Folds radiate from the points of tension.'],
    mistakes: ['Random lines that don’t follow the tension.', 'All the folds the same.', 'Outlining every fold.'],
    ex: 'Hang a cloth from one pin and draw the folds, then their shadows.',
    kids: 'Draw a superhero cape or a ghost sheet with folds.',
    adults: 'Draw drapery in charcoal on toned paper with white highlights.',
    mat: ['Plain cloth', 'Pins', 'Charcoal or pencil', 'Paper'], rel: ['light-form', 'charcoal', 'figure'] },

  /* ---------- teaching methods ---------- */
  { id: 'sketchbook', s: 'teach', n: 'Sketchbook habits', sum: 'Daily drawing, notes and experiments.', lvl: 1, mins: 15, ill: 'sketchbook',
    what: 'A sketchbook is a private space for practice, notes, experiments and ideas. Short, regular drawing in a sketchbook builds skill faster than occasional big pieces.',
    why: 'It builds a habit, takes the pressure off finished work and becomes a record of progress students can look back on.',
    steps: ['Choose a sketchbook that’s comfortable to carry.', 'Set a small, regular goal: one drawing a day, ten minutes.', 'Use prompts: draw your breakfast, your shoe, your view.', 'Write notes beside drawings: what worked, colours, ideas.', 'Glue in references, tickets and colour swatches.', 'Look back each month to see progress.'],
    tips: ['Make the first page messy on purpose to take away the fear.', 'Date each page.', 'Keep it private unless the student wants to share.'],
    mistakes: ['Only showing perfect drawings.', 'Tearing out pages.', 'Waiting for inspiration.'],
    ex: 'Start a week of daily ten-minute drawings with a prompt each day.',
    kids: 'Give a prompt jar and stickers for each page completed.',
    adults: 'Use the sketchbook for thumbnails and studies before every class project.',
    mat: ['A5 or A4 sketchbook', 'Pencil and pen', 'Glue stick'], rel: ['thumbnails', 'contour', 'gesture'] },
  { id: 'master-study', s: 'teach', n: 'Master studies', sum: 'Learning by copying great artists’ work.', lvl: 2, mins: 45, ill: 'mastercopy',
    what: 'A master study is a careful copy, or partial copy, of a work by an established artist, made to learn how they solved problems of colour, composition, brushwork or value.',
    why: 'Artists have learnt this way for centuries. Copying slowly reveals decisions that are invisible at a glance.',
    steps: ['Choose a work and one thing to study: composition, colour, brushwork or value.', 'Make a small value thumbnail first.', 'Copy the main shapes and proportions.', 'Match the values or colours as closely as you can.', 'Note what you learnt beside it.', 'Apply that lesson to your own work next.'],
    tips: ['Study one aspect at a time.', 'Use good-quality reproductions.', 'Label studies clearly as “after [artist]” and don’t sell copies.'],
    mistakes: ['Copying without a learning goal.', 'Starting with details.', 'Presenting a copy as original work.'],
    ex: 'Make a small study of one painting, focusing on how it uses light and dark.',
    kids: 'Make a picture in the style of an artist, such as Van Gogh’s swirls or Matisse’s cut-outs.',
    adults: 'Do a series of studies of one artist, then make an original piece using what you learnt.',
    mat: ['Reproductions of artworks', 'Media to match', 'Sketchbook'], rel: ['thumbnails', 'schemes', 'value-scale'] },
  { id: 'critique', s: 'teach', n: 'Kind, useful feedback', sum: 'Glow and grow, and how to run a gentle critique.', lvl: 1, mins: 15, ill: 'critique',
    what: 'Feedback in an art class works best when it’s specific, kind and useful. A simple structure is “glow and grow”: name one thing that works well (glow) and one thing to try next (grow).',
    why: 'It builds confidence, teaches students to look critically at art and creates a safe culture where people take risks.',
    steps: ['Set the rules: be kind, be specific, be helpful.', 'Lay the work out or pin it up.', 'Start with what the artist was trying to do.', 'Give glows first: specific strengths (“the shadow under the cup makes it sit on the table”).', 'Then one grow: a suggestion, framed as a question or “next time, try…”.', 'Let the artist respond and choose what to take on.'],
    tips: ['Comment on the work, not the person.', 'Model it yourself first.', 'Let students opt out of group feedback.'],
    mistakes: ['Vague praise (“nice”).', 'Too many suggestions at once.', 'Comparing students with each other.'],
    ex: 'Run a gallery walk where each student leaves one glow and one grow on sticky notes.',
    kids: 'Use star stickers for glows and an arrow for one grow.',
    adults: 'Use simple critique questions: what do you notice first, how does your eye move, what would you change?',
    mat: ['Sticky notes', 'Pins or a wall'], rel: ['demo', 'mixed-ages', 'sketchbook'] },
  { id: 'demo', s: 'teach', n: 'Demonstrating: I do, we do, you do', sum: 'Show it, try it together, then on their own.', lvl: 1, mins: 15, ill: 'demo',
    what: '“I do, we do, you do” (gradual release) is a teaching sequence: the teacher demonstrates and thinks aloud, the class tries a small step together with guidance, and then students practise independently while the teacher circulates.',
    why: 'It gives every student a clear model, a supported first try and space to work, which suits mixed abilities.',
    steps: ['I do: demonstrate the skill where everyone can see, talking through each decision.', 'Keep demos short (5 to 10 minutes) and focused on one skill.', 'We do: students try a small part with you, step by step.', 'Check everyone has it before moving on.', 'You do: students practise on their own project.', 'Circulate, give one-to-one tips, and pause the class if many share a problem.'],
    tips: ['Use a document camera or phone on a stand for close-up demos.', 'Show a mistake and fix it.', 'Leave the demo visible as a reference.'],
    mistakes: ['Long demos where students lose focus.', 'Skipping the “we do” step.', 'Doing it for the student on their own paper.'],
    ex: 'Plan your next lesson with a 5-minute demo, a 5-minute guided try and 30 minutes of independent work.',
    kids: 'Keep demos to 3 to 5 minutes and break them into tiny steps.',
    adults: 'Explain the why behind each step, not just the how.',
    mat: ['Demo board or easel', 'Phone stand or document camera (optional)'], rel: ['critique', 'mixed-ages', 'sketchbook'] },
  { id: 'pattern', s: 'teach', n: 'Pattern and repetition', sum: 'Repeating shapes and lines for mindful, decorative art.', lvl: 1, mins: 30, ill: 'pattern',
    what: 'Pattern drawing fills shapes with repeated lines, dots, scales, waves and other motifs. It’s decorative, very calming and a great way to practise control.',
    why: 'Patterns need no drawing experience, build pen control, focus attention and can be combined with any subject.',
    steps: ['Draw a big outline: an animal, a letter, a hand, a mandala.', 'Divide it into sections with flowing lines.', 'Fill each section with a different pattern.', 'Vary the density: some busy, some open.', 'Add shading along edges of sections for depth.', 'Add colour if you like.'],
    tips: ['Build a pattern library page first.', 'Leave some sections plain to rest the eye.', 'Slow, deliberate lines give the calmest result.'],
    mistakes: ['All patterns the same density.', 'Rushed, wobbly lines.', 'Too many tiny sections.'],
    ex: 'Fill an animal silhouette or a big letter with at least six patterns.',
    kids: 'Pattern-filled name art or animals with crayons.',
    adults: 'Use pattern work as a calming warm-up or a mindfulness activity.',
    mat: ['Fineliners', 'Pencil', 'Paper', 'Coloured pencils (optional)'], rel: ['marks', 'pen-ink', 'collage'] },
  { id: 'mixed-ages', s: 'teach', n: 'Teaching mixed ages and abilities', sum: 'One lesson, three levels of challenge.', lvl: 1, mins: 15, ill: 'mixedages',
    what: 'Mixed-ability teaching keeps everyone working on the same theme but at different levels of challenge: a supported version, a core task and a stretch task. Students choose or are guided to the right level.',
    why: 'Group classes often mix ages and experience. Planning levels keeps beginners from feeling lost and keeps experienced students engaged.',
    steps: ['Choose one subject or skill for the lesson.', 'Plan the core task most students will do.', 'Plan a support version: templates, simpler shapes, fewer steps.', 'Plan a stretch version: more values, a harder angle, a new medium.', 'Demonstrate the core task, and mention the other options.', 'Check in with each student and move them up or down as needed.'],
    tips: ['Let students choose their level; most choose well.', 'Pair experienced students with beginners to explain.', 'Praise effort and progress, not just results.'],
    mistakes: ['Teaching only to the middle.', 'Labelling levels as easy or hard in front of students.', 'Different subjects for each level, which splits the class.'],
    ex: 'Plan your next group lesson with support, core and stretch versions.',
    kids: 'Offer a starter template, a draw-your-own option and a challenge card.',
    adults: 'Offer extensions such as a limited palette, a time limit or a different medium.',
    mat: ['Templates and challenge cards', 'A range of materials'], rel: ['demo', 'critique', 'sketchbook'] },
);
const TECH_BY = Object.fromEntries(TECH.map(t => [t.id, t]));
